+@page "/dispatcher"
+@using Microsoft.AspNetCore.Authorization
+@attribute [Authorize]
+@rendermode InteractiveAuto
+@inject IShipmentService ShipmentService
+
+<PageTitle>Dispatcher Dashboard - ShipTrack</PageTitle>
+
+<h2 class="mb-4">Dispatcher Dashboard</h2>
+
+<div class="row mb-3">
+    <div class="col-md-4">
+        <label class="form-label">Filter by Status</label>
+        <select class="form-select" @bind="selectedStatus">
+            <option value="">All</option>
+            @foreach (var status in Enum.GetValues<ShipmentStatus>())
+            {
+                <option value="@status">@status</option>
+            }
+        </select>
+    </div>
+    <div class="col-md-4">
+        <label class="form-label">Search</label>
+        <input type="text" class="form-control" placeholder="Tracking # or destination..."
+               @bind="searchQuery" @bind:event="oninput" />
+    </div>
+</div>
+
+@if (shipments == null)
+{
+    <p><em>Loading shipments...</em></p>
+}
+else
+{
+    <div class="table-responsive">
+        <table class="table table-striped table-hover">
+            <thead class="table-dark">
+                <tr>
+                    <th>Tracking #</th>
+                    <th>Origin</th>
+                    <th>Destination</th>
+                    <th>Status</th>
+                    <th>Shipped Date</th>
+                    <th>Est. Delivery</th>
+                    <th>Update Status</th>
+                </tr>
+            </thead>
+            <tbody>
+                @foreach (var shipment in FilteredShipments)
+                {
+                    <tr>
+                        <td><strong>@shipment.TrackingNumber</strong></td>
+                        <td>@shipment.Origin</td>
+                        <td>@shipment.Destination</td>
+                        <td><span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></td>
+                        <td>@shipment.ShippedDate.ToString("MMM dd, yyyy")</td>
+                        <td>@shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
+                        <td>
+                            <select class="form-select form-select-sm" value="@((int)shipment.Status)"
+                                    @onchange="(e) => OnStatusChanged(shipment, e)">
+                                @foreach (var status in Enum.GetValues<ShipmentStatus>())
+                                {
+                                    <option value="@((int)status)">@status</option>
+                                }
+                            </select>
+                        </td>
+                    </tr>
+                }
+            </tbody>
+        </table>
+    </div>
+
+    @if (!FilteredShipments.Any())
+    {
+        <div class="alert alert-info">No shipments match your filters.</div>
+    }
+}
+
+@code {
+    private List<ShipmentDto>? shipments;
+    private string selectedStatus = "";
+    private string searchQuery = "";
+
+    private IEnumerable<ShipmentDto> FilteredShipments
+    {
+        get
+        {
+            if (shipments == null) return Enumerable.Empty<ShipmentDto>();
+
+            var result = shipments.AsEnumerable();
+
+            if (!string.IsNullOrEmpty(selectedStatus) && Enum.TryParse<ShipmentStatus>(selectedStatus, out var status))
+            {
+                result = result.Where(s => s.Status == status);
+            }
+
+            if (!string.IsNullOrEmpty(searchQuery))
+            {
+                var query = searchQuery.ToLowerInvariant();
+                result = result.Where(s =>
+                    s.TrackingNumber.Contains(query, StringComparison.OrdinalIgnoreCase) ||
+                    s.Destination.Contains(query, StringComparison.OrdinalIgnoreCase));
+            }
+
+            return result;
+        }
+    }
+
+    protected override async Task OnInitializedAsync()
+    {
+        shipments = await ShipmentService.GetAllShipmentsAsync();
+    }
+
+    private async Task OnStatusChanged(ShipmentDto shipment, ChangeEventArgs e)
+    {
+        if (int.TryParse(e.Value?.ToString(), out var statusValue))
+        {
+            var newStatus = (ShipmentStatus)statusValue;
+            var updated = await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, newStatus);
+            shipment.Status = updated.Status;
+            shipment.ActualDelivery = updated.ActualDelivery;
+        }
+    }
+
+    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
+    {
+        ShipmentStatus.Pending => "bg-secondary",
+        ShipmentStatus.PickedUp => "bg-info",
+        ShipmentStatus.InTransit => "bg-primary",
+        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
+        ShipmentStatus.Delivered => "bg-success",
+        ShipmentStatus.Returned => "bg-danger",
+        ShipmentStatus.Exception => "bg-danger",
+        _ => "bg-secondary"
+    };
+}
+

