+@page "/track"
+@using Microsoft.AspNetCore.Authorization
+@attribute [Authorize]
+@rendermode InteractiveAuto
+@inject IShipmentService ShipmentService
+
+<PageTitle>Track Shipment - ShipTrack</PageTitle>
+
+<h2 class="mb-4">Track a Shipment</h2>
+
+<div class="row mb-4">
+    <div class="col-md-6">
+        <div class="input-group">
+            <input type="text" class="form-control" placeholder="Enter tracking number (e.g., TRK-10483921)"
+                   @bind="trackingNumber" @onkeydown="OnKeyDown" />
+            <button class="btn btn-primary" @onclick="TrackShipment" disabled="@isLoading">
+                @if (isLoading)
+                {
+                    <span class="spinner-border spinner-border-sm me-1" role="status"></span>
+                }
+                Track
+            </button>
+        </div>
+    </div>
+</div>
+
+@if (notFound)
+{
+    <div class="alert alert-warning">
+        <strong>Not Found:</strong> No shipment found with tracking number "@searchedNumber".
+    </div>
+}
+
+@if (shipment != null)
+{
+    <div class="mb-4">
+        <div class="d-flex justify-content-between align-items-center flex-wrap gap-2 mb-3">
+            @{
+                var steps = new[] {
+                    ShipmentStatus.Pending,
+                    ShipmentStatus.PickedUp,
+                    ShipmentStatus.InTransit,
+                    ShipmentStatus.OutForDelivery,
+                    ShipmentStatus.Delivered
+                };
+                var currentIndex = Array.IndexOf(steps, shipment.Status);
+                var isException = shipment.Status == ShipmentStatus.Returned || shipment.Status == ShipmentStatus.Exception;
+            }
+            @foreach (var (step, i) in steps.Select((s, i) => (s, i)))
+            {
+                var isActive = !isException && i <= currentIndex;
+                var isCurrent = step == shipment.Status;
+                <div class="text-center flex-fill">
+                    <div class="rounded-circle d-inline-flex align-items-center justify-content-center @(isActive ? "bg-success text-white" : "bg-light text-muted border")"
+                         style="width: 40px; height: 40px; font-weight: bold;">
+                        @if (isActive && !isCurrent)
+                        {
+                            <span>✓</span>
+                        }
+                        else
+                        {
+                            <span>@(i + 1)</span>
+                        }
+                    </div>
+                    <div class="small mt-1 @(isCurrent ? "fw-bold" : "")">@step</div>
+                </div>
+            }
+        </div>
+
+        @if (isException)
+        {
+            <div class="alert alert-danger">
+                <strong>@shipment.Status:</strong> This shipment has an exception status.
+            </div>
+        }
+    </div>
+
+    <div class="card">
+        <div class="card-header d-flex justify-content-between align-items-center">
+            <h5 class="mb-0">@shipment.TrackingNumber</h5>
+            <span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">@shipment.Status</span>
+        </div>
+        <div class="card-body">
+            <div class="row">
+                <div class="col-md-6">
+                    <p><strong>Origin:</strong> @shipment.Origin</p>
+                    <p><strong>Destination:</strong> @shipment.Destination</p>
+                    <p><strong>Route:</strong> @shipment.Origin → @shipment.Destination</p>
+                    <p><strong>Weight:</strong> @shipment.WeightKg kg</p>
+                </div>
+                <div class="col-md-6">
+                    <p><strong>Shipped Date:</strong> @shipment.ShippedDate.ToString("MMM dd, yyyy")</p>
+                    <p><strong>Estimated Delivery:</strong> @shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</p>
+                    @if (shipment.ActualDelivery.HasValue)
+                    {
+                        <p><strong>Actual Delivery:</strong> @shipment.ActualDelivery.Value.ToString("MMM dd, yyyy")</p>
+                    }
+                    <p><strong>Recipient:</strong> @shipment.RecipientName (@shipment.RecipientEmail)</p>
+                </div>
+            </div>
+            @if (!string.IsNullOrEmpty(shipment.Notes))
+            {
+                <hr />
+                <p><strong>Notes:</strong> @shipment.Notes</p>
+            }
+        </div>
+    </div>
+}
+
+@code {
+    private string trackingNumber = "";
+    private string searchedNumber = "";
+    private ShipmentDto? shipment;
+    private bool notFound;
+    private bool isLoading;
+
+    private async Task TrackShipment()
+    {
+        if (string.IsNullOrWhiteSpace(trackingNumber)) return;
+
+        isLoading = true;
+        notFound = false;
+        shipment = null;
+        searchedNumber = trackingNumber.Trim();
+
+        shipment = await ShipmentService.GetByTrackingNumberAsync(searchedNumber);
+        notFound = shipment == null;
+        isLoading = false;
+    }
+
+    private async Task OnKeyDown(KeyboardEventArgs e)
+    {
+        if (e.Key == "Enter")
+            await TrackShipment();
+    }
+
+    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
+    {
+        ShipmentStatus.Pending => "bg-secondary",
+        ShipmentStatus.PickedUp => "bg-info",
+        ShipmentStatus.InTransit => "bg-primary",
+        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
+        ShipmentStatus.Delivered => "bg-success",
+        ShipmentStatus.Returned => "bg-danger",
+        ShipmentStatus.Exception => "bg-danger",
+        _ => "bg-secondary"
+    };
+}
+

